const ids=['SbcAb0YDNv6PLqpq5XAlze41BM.jpg','F487AXTxDP4zFhdlhNPN7uwgOIk.jpg','ykCmCfzhgrEyaaT99BSLyOoMNM.jpg','EoNwdwx3ZekuUUuEq2qz2xyKs.jpg','CumijdagSnZBJbds0DhbHzN6mC8.jpg','9zq6Gjzblvy4WlyHuEPdtga60.jpg','G86SeqqiZSDPrtSVR4wKSJI8c.png','0tXpYw1WwCYHCuAWYCWVFWv2zw.jpg','rxKNlFDEZmSLTHwtMWhJtirYM.jpg','76tAQEmcHIUgnYvD4xULbFXfKw.jpg','dGUd0Tyud5daPsNiOkRFsbiZD4.png'];const gallery=document.querySelector('.gallery'),rail=document.querySelector('.rail');ids.forEach((id,i)=>{const f=document.createElement('figure');f.className='frame'+(i===2?' tall':'');f.id='image-'+(i+1);const img=new Image();img.src='https://framerusercontent.com/images/'+id+'?width=1860';img.alt='FROMANOTHER project preview '+(i+1);img.loading=i<2?'eager':'lazy';f.append(img);gallery.append(f);const b=document.createElement('button');b.setAttribute('aria-label','Go to image '+(i+1));b.onclick=()=>f.scrollIntoView({behavior:'smooth',block:'center'});rail.append(b)});const frames=[...document.querySelectorAll('.frame')],dots=[...rail.children],observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('show');dots[frames.indexOf(e.target)]?.classList.add('active')}else dots[frames.indexOf(e.target)]?.classList.remove('active')}),{threshold:.17});frames.forEach(f=>observer.observe(f));let ticking=false;addEventListener('scroll',()=>{if(ticking)return;ticking=true;requestAnimationFrame(()=>{const h=innerHeight;for(const f of frames){const r=f.getBoundingClientRect();if(r.bottom<0||r.top>h)continue;f.firstElementChild.style.transform=`translate3d(0,${((r.top+r.height/2-h/2)/h)*-45}px,0)`}ticking=false})},{passive:true});document.querySelector('#menuToggle').onclick=()=>{const nav=document.querySelector('#menu'),open=nav.classList.toggle('closed');document.querySelector('#menuToggle').setAttribute('aria-expanded',String(!open))};document.querySelector('#audioToggle').onclick=e=>{const pressed=e.currentTarget.getAttribute('aria-pressed')==='true';e.currentTarget.setAttribute('aria-pressed',String(!pressed));e.currentTarget.textContent=pressed?'Off —':'On —'};const updateClock=()=>{document.querySelector('#clock').textContent='HCMC, '+new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Ho_Chi_Minh',hour:'2-digit',minute:'2-digit'}).format(new Date())};updateClock();setInterval(updateClock,60000);const c=document.querySelector('.cursor');addEventListener('pointermove',e=>{c.style.opacity='1';c.style.transform=`translate(${e.clientX-18}px,${e.clientY-18}px)`});

// Match the Portfolio loader: 000 → 100, cat line drawing and upward exit.
(()=>{const loader=document.getElementById('intro-loader'),number=loader?.querySelector('.loader-progress');if(!loader)return;if(matchMedia('(prefers-reduced-motion: reduce)').matches){if(number)number.textContent='100';loader.classList.add('is-done');return}const start=performance.now(),duration=1450;function tick(now){const t=Math.min(1,(now-start)/duration),v=1-Math.pow(1-t,2);if(number)number.textContent=String(Math.round(v*100)).padStart(3,'0');if(t<1)requestAnimationFrame(tick)}requestAnimationFrame(tick);setTimeout(()=>loader.classList.add('is-done'),1550)})();
